SELECT ENO
  FROM EMP
 WHERE SAL > (SELECT AVG(SAL) FROM EMP);

SELECT ENO
  FROM EMP
 WHERE SAL > ALL (SELECT SAL FROM EMP WHERE DNO = 20);

SELECT ENO
  FROM EMP
 WHERE DNO IN (SELECT DNO FROM DEPT WHERE LOC = 'SEOUL');

SELECT ENO
  FROM EMP
 WHERE SAL > ANY (SELECT SAL FROM EMP WHERE DNO = 20);

SELECT ENO
  FROM EMP
 WHERE SAL < ALL (SELECT SAL FROM EMP WHERE DNO = 20);

SELECT DNO
  FROM DEPT
 WHERE DNO NOT IN (SELECT DNO FROM EMP);

SELECT D.DNAME
  FROM DEPT D
 WHERE EXISTS (SELECT 1 FROM EMP E WHERE E.DNO = D.DNO);

SELECT D.DNAME
  FROM DEPT D
 WHERE D.DNO IN (SELECT E.DNO FROM EMP E);

SELECT ENO
  FROM EMP
 WHERE SAL = (SELECT SAL FROM EMP WHERE ENO = 99);

SELECT ENAME, SAL - (SELECT AVG(SAL) FROM EMP) AS DIFF
  FROM EMP
 WHERE ENAME = 'C';
